   GFX_PIC * oh = ( GFX_PIC *)overimage;
   INT loop, i, addnum;
   INT x2 = x + oh->width - 1;
   INT y2 = y + oh->height - 1;

   if ( x >=0 && y >=0 && x2 < bh->width && y2 < bh->height )
   {
      baseimage += sizeof ( GFX_PIC );
      baseimage += ( x + ( y * bh->width ) );

      overimage += sizeof ( GFX_PIC );

      addnum = bh->width - oh->width;

