      if ( fadeflag )
      {
         if ( fadecnt >= FADE_FRAMES - 1 )
         {
            RAP_ClearSides();
            g_mapleft = MAP_LEFT;
            GFX_SetPalette ( gpal, 0 );
            fadeflag = FALSE;
            g_oldsuper = EMPTY;
            g_oldshield = EMPTY;
         }
         else
         {
            RAP_ClearSides();
            GFX_SetRetraceFlag ( TRUE );
            GFX_FadeFrame ( gpal, fadecnt, FADE_FRAMES );
            GFX_SetRetraceFlag ( FALSE );
            g_mapleft = MAP_LEFT + shakes [ fadecnt ];
            fadecnt++;
         }
      }
      else
      {
         if ( !init_flag )
            RAP_PaletteStuff();
      }

      RAP_DisplayStats();

      while ( FRAME_COUNT - local_cnt < 3 );
      local_cnt = FRAME_COUNT;

      if ( fadeflag )
         TILE_ShakeScreen();
      else
         TILE_DisplayScreen();

      if ( startfadeflag )
      {
         SND_Patch ( FX_GEXPLO, 127 );
         SND_Patch ( FX_AIREXPLO, 127 );
         GFX_SetRetraceFlag ( TRUE );
         GFX_FadeOut ( 63, 60, 60, 1 );
         GFX_FadeStart();
         startfadeflag = FALSE;
         fadeflag = TRUE;
         fadecnt = 0;
         GFX_SetRetraceFlag ( FALSE );
      }

      if ( reg_flag && KBD_Key ( SC_BACKSPACE ) )
      {
         OBJS_Add ( S_DEATH_RAY );
         OBJS_Add ( S_ENERGY );
         OBJS_Add ( S_ENERGY );
         OBJS_Add ( S_ENERGY );
         plr.score = 0;
      }

      if ( init_flag )
      {
         init_flag = FALSE;
         GFX_FadeIn ( gpal, 64 );
      }

      if ( KBD_Key ( SC_X ) && KBD_Key ( SC_ALT ) )
      {
         RAP_ClearSides();
         SWD_SetClearFlag ( FALSE );
         IPT_End();
         WIN_AskExit();
         IPT_Start();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
         SWD_SetClearFlag ( TRUE );
         IMS_StartAck();
         BUT_1 = FALSE;
         BUT_2 = FALSE;
         BUT_3 = FALSE;
         BUT_4 = FALSE;
         b2_flag = FALSE;
         b3_flag = FALSE;
      }

      if ( KBD_IsKey ( SC_ESC ) )
      {
         if ( godmode )
            end_wave = TRUE;

         if ( demo_mode == DEMO_OFF )
         {
            SWD_SetClearFlag ( FALSE );
            IPT_End();
            RAP_ClearSides();
            if ( WIN_AskBool ( "Abort Mission ?" ) )
            {
               plr.score = start_score;
               rval = TRUE;
               break;
            }
            IPT_Start();
            g_oldsuper = EMPTY;
            g_oldshield = EMPTY;
            RAP_ClearSides();
            RAP_DisplayStats();
            SWD_SetClearFlag ( TRUE );
            IMS_StartAck();
            BUT_1 = FALSE;
            BUT_2 = FALSE;
            BUT_3 = FALSE;
            BUT_4 = FALSE;
            b2_flag = FALSE;
            b3_flag = FALSE;
         }
         else if ( demo_mode == DEMO_PLAYBACK )
         {
            rval = TRUE;
            break;
         }
         else if ( demo_mode == DEMO_RECORD )
            break;
      }

      if ( end_wave )
         break;
   }
  
   GFX_FadeOut ( 0, 0, 0, 32 );

   RAP_FreeMap();
   end_wave = FALSE;

   memset ( displaybuffer, 0, 64000 );
   GFX_MarkUpdate( 0, 0, 320, 200 );

   IPT_PauseControl ( FALSE );
  
   GFX_DisplayUpdate();
   GFX_SetPalette ( palette, 0 );
   IPT_End();

   if ( demo_flag == DEMO_RECORD )
      DEMO_SaveFile();

   return ( rval );
}
  
