/***************************************************************************
   InitMobj() - Inits an object to be moved
 ***************************************************************************/
VOID
InitMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
)
{
   cur->done = FALSE;
   cur->addx = 1;
   cur->addy = 1;
  
   cur->delx = cur->x2 - cur->x;
   cur->dely = cur->y2 - cur->y;
  
   if ( cur->delx < 0 )
   {
      cur->delx = -cur->delx;
      cur->addx = -cur->addx;
   }
   if ( cur->dely < 0 )
   {
      cur->dely = -cur->dely;
      cur->addy = -cur->addy;
   }
  
   if ( cur->delx >= cur->dely )
   {
      cur->err = -(cur->dely>>1);
      cur->maxloop = cur->delx + 1;
   }
   else
   {
      cur->err = (cur->delx>>1);
      cur->maxloop = cur->dely + 1;
   }
}
  
/***************************************************************************
   MoveMobj() - gets next postion for an Object
 ***************************************************************************/
VOID
MoveMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
)
{
   if ( cur->maxloop == 0 )
   {
      cur->done = TRUE;
      return;
   }
  
   if ( cur->delx >= cur->dely )
   {
      cur->x += cur->addx;
      cur->err += cur->dely;
  
      if ( cur->err > 0 )
      {
         cur->y += cur->addy;
         cur->err -= cur->delx;
      }
   }
   else
   {
      cur->y += cur->addy;
      cur->err += cur->delx;
  
      if ( cur->err > 0 )
      {
         cur->x += cur->addx;
         cur->err -= cur->dely;
      }
   }
  
   cur->maxloop--;
}

/***************************************************************************
   MoveSobj() - gets next postion for an Object at speed
 ***************************************************************************/
INT
MoveSobj(
MOVEOBJ * cur,             // INPUT : pointer to MOVEOBJ
INT       speed            // INPUT : speed to plot at
)
{
   if ( speed == 0 ) return ( 0 );

   if ( cur->delx >= cur->dely )
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;
         cur->x += cur->addx;
         cur->err += cur->dely;
  
         if ( cur->err > 0 )
         {
            cur->y += cur->addy;
            cur->err -= cur->delx;
         }
      }
   }
   else
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;
         cur->y += cur->addy;
         cur->err += cur->delx;
  
         if ( cur->err > 0 )
         {
            cur->x += cur->addx;
            cur->err -= cur->dely;
         }
      }
   }
  
   if ( cur->maxloop < 1 )
      cur->done = TRUE;

   return ( speed );
}

